insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-st-103', 'chemistry-stoichiometry', 'chemistry', 'Dalton’s law of multiple proportions applies when two elements form more than one compound. The masses of one element that combine with a fixed mass of the other stand in', '["a simple whole-number ratio","an irrational ratio","the ratio of their densities","a 1:1 mass ratio always"]'::jsonb, 0, 'Different compounds of the same two elements show small-integer mass ratios for one element at fixed mass of the other.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'easy', 'laws-combination') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
