insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-st-106', 'chemistry-stoichiometry', 'chemistry', 'The law of reciprocal proportions (Richter) compares how two elements A and B each combine with a fixed mass of a third element C. The A:B mass ratio so obtained is', '["the same as, or a simple multiple of, the ratio in which A and B combine with each other","always 1:1 by mass","equal to their atomic numbers","independent of any compound of A with B"]'::jsonb, 0, 'Masses of A and B that combine with a fixed mass of C match the combining ratio of A with B, or a simple multiple of it.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'easy', 'laws-combination') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
