insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-st-108', 'chemistry-stoichiometry', 'chemistry', 'Carbon forms two oxides. With 12 g of carbon, one oxide contains 16 g of oxygen and the other contains 32 g of oxygen. These oxygen masses illustrate multiple proportions because their ratio is', '["1 : 2","2 : 3","3 : 4","1 : 1"]'::jsonb, 0, 'For a fixed 12 g of carbon the oxygen masses 16 g and 32 g stand in the simple ratio 1 : 2.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'medium', 'laws-combination') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
